# [SAME-SCENARIO] summarize_text.py\nimport os\nfrom model_client import get_llm_client\nfrom model_models import PromptRequest, normalize_response\n\ndef summarize_text(text: str) -> str:\n    """Generate a concise summary of the provided long text using a hosted LLM.\n    Uses the provider configured in environment variables."""\n    client = get_llm_client()\n    request = PromptRequest(\n        messages=[{"role": "user", "content": f"Summarize the following text in three sentences:\\n{text}"}],\n        model="gpt-4o-mini",  # Model identifier for the selected provider\n    )\n    response = client.chat_completions(request)\n    result = normalize_response(response)\n    return result["choices"][0]["message"]["content"]